CREATE PROCEDURE SP_Vue_SalesInvoice_Pcs (@Id Varchar(100)) AS 
BEGIN 
DECLARE @sql1 NVARCHAR(MAX);

SET @sql1 = 'ALTER VIEW  Vue_SalesInvoice as SELECT Mas_Buyer.BuyerName, Mas_Exporter.ExporterName, (cast(Mas_Exporter.ExporterAddress as Varchar(5000))) ExporterAddress, Mas_Exporter.Phone, Mas_Exporter.TIN, Mas_Exporter.CST, Mas_exporter.GSTNo, Mas_Party.Pname, (Cast(Mas_Party.Paddress as Varchar(500)))Paddress, Mas_Party.Phone PPhine, Mas_Party.TIN PTIN, Mas_Party.CST PCST,mas_Party.GSTNo PGSTNo, OrderMas.BuyOrdNo, '''' as Docno,TJW.dt as DcDate, '''' Dcfinyear, sum(TPD.TotPcs) Kg, TPD.JRate Rate, SUm(TPD.Amount)Amount, TJW.ID, TJW.Finyear iFinyear, case when len(isnull(Mas_SalesGrp.Sales_Inv_Pcs_Prefix,'''')) >0 then Rtrim(isNull(Mas_SalesGrp.Sales_Inv_Pcs_Prefix,'''')) +'' ''+ Rtrim(TJW.Invno) Else Rtrim(TJW.Invno) END as Invno, TJW.Dt InvDt, TJW.InvFlg,  TPD.StyleNo, OrderMas.Jobno, OrderMas.Finyear, Mas_State.StateName ExpStateName,Mas_State.Statecode ExpStateCode, isnull(Mas_partyState.StateName,'''')partyState,isnull(Mas_partyState.Statecode,'''') PartyStateCode,RTRIM(Jobno)+''/''+Ordermas.Finyear+''->''+BuyOrdNo +''/''+TPD.StyleNo  Descr,TPD.HSNID ,Mas_HSN_NEW.HSNCode,Case when isnull(Mas_Exporter.Stateid,0)=isnull(Mas_party.Stateid,0) then TPD.HSN_Percent /2  else 0 end as rate1,Case when isnull(Mas_Exporter.Stateid,0)=isnull(Mas_party.Stateid,0) then TPD.HSN_Percent /2  else 0 end as rate2,Case when Mas_Exporter.Stateid<>Mas_party.Stateid then  TPD.HSN_Percent else 0 end as Rate3, Case when isnull(Mas_Exporter.Stateid,0)=isnull(Mas_party.Stateid,0) then (sum(TPD.Amount)* isnull(TPD.HSN_Percent,0)/2)/100 ELSE 0 END AS GSTAmount1,Case when isnull(Mas_Exporter.Stateid,0)=isnull(Mas_party.Stateid,0) then (sum(TPD.Amount)* isnull(TPD.HSN_Percent,0)/2)/100 ELSE 0 END AS GSTAmount2,Case when Mas_Exporter.Stateid<>Mas_party.Stateid then (sum(TPD.Amount)* isnull(TPD.HSN_Percent,0))/100 ELSE 0 END AS Amount3,(Sum(TPD.Amount)+Case when isnull(Mas_Exporter.Stateid,0)=isnull(Mas_party.Stateid,0) then (Sum(TPD.Amount)*(isnull(TPD.HSN_Percent,0)/2)/100) ELSE 0 END + Case when isnull(Mas_Exporter.Stateid,0)=isnull(Mas_party.Stateid,0) then (Sum(TPD.Amount)*(isnull(TPD.HSN_Percent,0)/2)/100) ELSE 0 END + Case when Mas_Exporter.Stateid<>Mas_party.Stateid then (Sum(TPD.Amount)*(isnull(TPD.HSN_Percent,0))/100) ELSE 0 END) as tot,IsNull(Mas_Vehicle.VName,'''') As VName ,''PCS''UOM,isnull(ReverseCharge,0)ReverseCharge,Isnull(TransPortationMode,'''')TransPortationMode,IsNull(TJW.VehicleId,0) As VehicleId,IsNull(Mas_Bank.CurrAcc,'''') CurrAcc ,IsNull(Mas_Bank.IFSCCode,'''') IFSCCode,MAs_Bank.BankName as BankName,TJW.Delivery,TJW.REMARKS FROM  Trs_JobWrkInv TJW INNER JOIN (Select InvId,WorkDet,sum(TotPcs) as totPcs,JRate,Sum(Amount) as Amount ,Remarks,OrdId,StyleNo,colid,Colordesc,VName,SizeDesc,NetRate,no_of_box,pcs_per_box,HsnId,HSN_Percent from TempPcsDCDetInv  group by InvId,WorkDet,JRate,Remarks,OrdId,StyleNo,colid,Colordesc,VName,SizeDesc,NetRate,no_of_box,pcs_per_box,HsnId,HSN_Percent ) as TPD ON TJW.ID=TPD.InvId LEFT OUTER JOIN Mas_Party Mas_Party ON TJW.PartyName=Mas_Party.PID INNER JOIN OrderMas OrderMas ON TPD.OrdId=OrderMas.OrdId INNER JOIN OrderMas2 ON OrderMas.Ordid = OrderMas2.Ordid INNER JOIN Mas_Exporter Mas_Exporter ON OrderMas.ExpID=Mas_Exporter.ExpID LEFT OUTER JOIN Mas_Buyer Mas_Buyer ON OrderMas.BuyerID=Mas_Buyer.BuyerID left outer join Mas_State on Mas_State.id=Mas_Exporter.Stateid left Outer Join Mas_State Mas_partyState On Mas_partyState.Id=Mas_Party.Stateid left join mas_vehicle on TJW.vehicleid=Mas_Vehicle.code LEFT OUTER JOIN Mas_Bank Mas_Bank on Mas_Bank.BankId =Mas_Exporter.BankId LEFT JOIN MAS_HSN as Mas_HSN_NEW ON TPD.HSNID = Mas_HSN_NEW.ID left join Mas_SalesGrp on OrderMas.ExpId  = Mas_SalesGrp.Coycode WHERE TJW.ID = ''' + @id + ''' group by Mas_Buyer.BuyerName,Mas_Exporter.ExporterName,(cast(Mas_Exporter.ExporterAddress as Varchar(5000))),Mas_Exporter.Phone,Mas_Exporter.TIN,Mas_Exporter.CST,Mas_Exporter.GSTNo,Mas_Party.Pname,(Cast(Paddress as Varchar(500))),Mas_Party.Phone,Mas_Party.TIN,Mas_Party.CST,Mas_Party.GSTNo,Ordermas.BuyOrdNo,TPD.JRate,TJW.ID,TJW.Finyear,TJW.Invno,TJW.Dt,TJW.InvFlg,TPD.StyleNo,OrderMas.Jobno, OrderMas.Finyear, Mas_State.StateName,Mas_Exporter.Stateid,Mas_partyState.StateName,Mas_Party.Stateid,OrderMas2.StyleNo,IsNull(Mas_Vehicle.VName,''''),TJW.ReverseCharge,TJW.TransPortationMode,IsNull(TJW.VehicleId,0),IsNull(Mas_Bank.CurrAcc,''''),IsNull(Mas_Bank.IFSCCode,''''),Mas_State.Statecode,Mas_partyState.StateCode,MAs_Bank.BankName,TJW.Delivery,TJW.REMARKS,TPD.HSNID,TPD.HSN_Percent,Mas_HSN_NEW.HSNCode,Mas_SalesGrp.Sales_Inv_Pcs_Prefix'

EXEC sp_executesql @sql1 

END